#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    long long *w = (long long *)malloc((N + 1) * sizeof(long long));
    long long *pref = (long long *)malloc((N + 1) * sizeof(long long));
    if (!w || !pref) return 0;

    for (int i = 1; i <= N; i++) scanf("%lld", &w[i]);

    pref[0] = 0;
    for (int i = 1; i <= N; i++) pref[i] = pref[i - 1] + w[i];

    if (N <= 1) {
        printf("0\n");
        free(w);
        free(pref);
        return 0;
    }

    long long **dp = (long long **)malloc((N + 2) * sizeof(long long *));
    int **opt = (int **)malloc((N + 2) * sizeof(int *));
    if (!dp || !opt) return 0;

    for (int i = 0; i <= N + 1; i++) {
        dp[i] = (long long *)malloc((N + 2) * sizeof(long long));
        opt[i] = (int *)malloc((N + 2) * sizeof(int));
        if (!dp[i] || !opt[i]) return 0;
    }

    for (int i = 1; i <= N; i++) {
        dp[i][i] = 0;
        opt[i][i] = i;
    }

    for (int len = 2; len <= N; len++) {
        for (int l = 1; l + len - 1 <= N; l++) {
            int r = l + len - 1;
            long long sum = pref[r] - pref[l - 1];

            int start = opt[l][r - 1];
            int end = opt[l + 1][r];
            if (start < l) start = l;
            if (end > r - 1) end = r - 1;

            long long best = LLONG_MAX;
            int bestk = start;

            for (int k = start; k <= end; k++) {
                long long val = dp[l][k] + dp[k + 1][r] + sum;
                if (val < best) {
                    best = val;
                    bestk = k;
                }
            }

            dp[l][r] = best;
            opt[l][r] = bestk;
        }
    }

    printf("%lld\n", dp[1][N]);

    for (int i = 0; i <= N + 1; i++) {
        free(dp[i]);
        free(opt[i]);
    }
    free(dp);
    free(opt);
    free(w);
    free(pref);

    return 0;
}

