    };

    const long long INF = (1LL << 62);
    vector<vector<long long>> dp(N + 2, vector<long long>(N + 2, 0));

    // dp[l][r] = minimum cost to cut segment [l..r] into 1-cm pieces
    for (int len = 2; len <= N; ++len) {
        for (int l = 1; l + len - 1 <= N; ++l) {
            int r = l + len - 1;
            dp[l][r] = INF;
            long long s = sum(l, r);
            for (int k = l; k < r; ++k) {
                dp[l][r] = min(dp[l][r], dp[l][k] + dp[k + 1][r] + s);
            }
        }
    }

    cout << dp[1][N] << '\n';
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] w = new long[n + 1];
        long[] prefix = new long[n + 1];
        for (int i = 1; i <= n; i++) {
            w[i] = sc.nextLong();
            prefix[i] = prefix[i-1] + w[i];
        }

        long[][] dp = new long[n + 1][n + 1];
        // dp[i][j] = min cost to fully cut segment [i..j]
        // length 1: dp[i][i] = 0

        for (int len = 2; len <= n; len++) {
            for (int i = 1; i + len - 1 <= n; i++) {
                int j = i + len - 1;
                long segSum = prefix[j] - prefix[i-1];
                dp[i][j] = Long.MAX_VALUE / 2;
                for (int k = i; k < j; k++) {
                    dp[i][j] = Math.min(dp[i][j], segSum + dp[i][k] + dp[k+1][j]);
                }
            }
        }

        System.out.println(dp[1][n]);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N = fs.nextInt();

        long[] w = new long[N + 1];
        long[] prefix = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            w[i] = fs.nextLong();
            prefix[i] = prefix[i - 1] + w[i];
        }

        if (N <= 1) {
            System.out.println(0);
            return;
        }

        long[][] dp = new long[N + 2][N + 2];
        int[][] opt = new int[N + 2][N + 2];

        for (int i = 1; i <= N; i++) {
            dp[i][i] = 0;
            opt[i][i] = i;
        }

        for (int len = 2; len <= N; len++) {
            for (int l = 1; l + len - 1 <= N; l++) {
                int r = l + len - 1;
                long sum = prefix[r] - prefix[l - 1];

                long best = Long.MAX_VALUE;
                int bestK = -1;

                int start = opt[l][r - 1];
                int end = opt[l + 1][r];
                if (start < l) start = l;
                if (end > r - 1) end = r - 1;

                for (int k = start; k <= end; k++) {
                    long val = dp[l][k] + dp[k + 1][r] + sum;
                    if (val < best) {
                        best = val;
                        bestK = k;
                    }
                }

                dp[l][r] = best;
                opt[l][r] = bestK;
            }
        }

        System.out.println(dp[1][N]);
    }
}
